window.docContents[15].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/5___25___2___-1-dimensional-representations/#Chapter5___Discussion_1dim_reps":{"contents":"Therefore,\n\nG/[G, G] \\cong \\mathbb{F}_q^\\times \\quad \\text{via } g \\mapsto \\det(g).\n\nThe 1-dimensional representations of G thus have the form\n\n\\rho(g) = \\xi\\bigl(\\det(g)\\bigr),\n\nwhere \\xi is a homomorphism\n\n\\xi : \\mathbb{F}_q^\\times \\to \\mathbb{C}^\\times;\n\nso there are q - 1 such representations, denoted \\mathbb{C}_\\xi.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.25. Representations of $GL_2(\\mathbb{F}_q)$\t5.25.2. 1-dimensional representations\tG/[G,G] ≅ F_q^× and description of 1-dimensional representations C_xi","header":"G/[G,G] ≅ F_q^× and description of 1-dimensional representations C_xi","id":"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/5___25___2___-1-dimensional-representations/#Chapter5___Discussion_1dim_reps"},"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Section-9___6___-Finite-abelian-categories/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___6___-Finite-abelian-categories--Section-9___6___-Finite-abelian-categories":{"contents":"\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.6. Finite abelian categories","header":"Section 9.6: Finite abelian categories","id":"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Section-9___6___-Finite-abelian-categories/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___6___-Finite-abelian-categories--Section-9___6___-Finite-abelian-categories"}});
